import"./chunk-VC46IEJQ.js";var e=(r,i,s,a,h,l,o,n,t)=>({name:{en:r,zh:i},desc:{en:s[0],zh:s[1]},tour:{en:a[0],zh:a[1]},source:{confidence:h,refs:l,book:{en:o[0],zh:o[1]},unknown:{en:n[0],zh:n[1]},interpretation:{en:t[0],zh:t[1]}}}),d={id:"valyria",intro:{en:"The Freehold of Valyria was the greatest power of the old world until the Doom destroyed it. Sailors shun the Smoking Sea and no reliable eyewitness account survives, so this scene is a restrained, haunted impression, not a map.",zh:"\u74E6\u96F7\u5229\u4E9A\u81EA\u7531\u5821\u5792\u66FE\u662F\u53E4\u4EE3\u4E16\u754C\u6700\u5F3A\u5927\u7684\u52BF\u529B\uFF0C\u76F4\u5230\u672B\u65E5\u6D69\u52AB\u5C06\u5176\u6BC1\u706D\u3002\u6C34\u624B\u4EEC\u907F\u5F00\u70DF\u6D77\uFF0C\u4E5F\u6CA1\u6709\u53EF\u9760\u7684\u76EE\u51FB\u8BB0\u5F55\u6D41\u4F20\u4E0B\u6765\uFF0C\u6240\u4EE5\u672C\u573A\u666F\u53EA\u662F\u514B\u5236\u800C\u5E7D\u6697\u7684\u610F\u8C61\uFF0C\u800C\u975E\u5730\u56FE\u3002"},notes:{en:"From the novels: the Doom, the Smoking Sea that sailors fear, a red glow in the sky glimpsed from a passing ship, Euron Greyjoy's unverified claim to have walked the ruins, and Valyrian roads and fused stone surviving elsewhere in Essos and Westeros. From the companion book: the Fourteen Flames, and a peninsula broken into islands. Everything shown here - layout, ruins, towers, glowing fissures, glassy slag - is interpretation. No inhabitant, dragon or monster is shown.",zh:"\u5C0F\u8BF4\u53EF\u636E\uFF1A\u672B\u65E5\u6D69\u52AB\u3001\u4EE4\u6C34\u624B\u754F\u60E7\u7684\u70DF\u6D77\u3001\u8FC7\u5F80\u8239\u53EA\u671B\u89C1\u7684\u5929\u8FB9\u7EA2\u5149\u3001\u6538\u4F26\xB7\u845B\u96F7\u4E54\u4F0A\u81EA\u79F0\u8E0F\u8DB3\u5E9F\u589F\uFF08\u65E0\u4ECE\u8BC1\u5B9E\uFF09\uFF0C\u4EE5\u53CA\u5728\u5384\u7D22\u65AF\u4E0E\u7EF4\u65AF\u7279\u6D1B\u522B\u5904\u7559\u5B58\u7684\u74E6\u96F7\u5229\u4E9A\u5927\u9053\u548C\u7194\u77F3\u5EFA\u7B51\u3002\u8BBE\u5B9A\u96C6\u53EF\u636E\uFF1A\u5341\u56DB\u706B\u5CF0\uFF0C\u4EE5\u53CA\u788E\u88C2\u6210\u7FA4\u5C9B\u7684\u534A\u5C9B\u3002\u753B\u9762\u4E2D\u7684\u4E00\u5207\u2014\u2014\u5E03\u5C40\u3001\u5E9F\u589F\u3001\u5854\u697C\u3001\u53D1\u5149\u7684\u88C2\u9699\u3001\u73BB\u7483\u72B6\u7194\u6E23\u2014\u2014\u5747\u4E3A\u60F3\u8C61\u3002\u573A\u666F\u4E2D\u4E0D\u51FA\u73B0\u5C45\u6C11\u3001\u9F99\u6216\u602A\u7269\u3002"},tour:["smoking-sea","fourteen-flames","valyrian-road","shattered-towers","fused-stone","fire-fissures"],sources:[{ref:"adwd",checked:"search-snippet",note:{en:"On Tyrion's voyage east, a dull red glow is seen in the sky while passing Valyria; Valyrian roads appear on his journey from Pentos. Recalled, and the red glow confirmed via a wiki search summary.",zh:"\u63D0\u5229\u6602\u4E1C\u884C\u9014\u4E2D\uFF0C\u8239\u7ECF\u74E6\u96F7\u5229\u4E9A\u9644\u8FD1\u65F6\u671B\u89C1\u5929\u8FB9\u4E00\u7247\u6697\u7EA2\u5149\u8292\uFF1B\u4ED6\u4ECE\u6F58\u6258\u65AF\u51FA\u53D1\u7684\u65C5\u7A0B\u4E2D\u4E5F\u8D70\u8FC7\u74E6\u96F7\u5229\u4E9A\u5927\u9053\u3002\u51ED\u8BB0\u5FC6\uFF0C\u7EA2\u5149\u4E00\u8282\u7ECF\u7EF4\u57FA\u641C\u7D22\u6458\u8981\u5370\u8BC1\u3002"}},{ref:"affc",checked:"search-snippet",note:{en:"Euron Greyjoy claims his dragon horn came from the ruins of Valyria; it is only his claim. Confirmed via a wiki search summary.",zh:"\u6538\u4F26\xB7\u845B\u96F7\u4E54\u4F0A\u58F0\u79F0\u4ED6\u7684\u9F99\u89D2\u53D6\u81EA\u74E6\u96F7\u5229\u4E9A\u5E9F\u589F\uFF0C\u4F46\u8FD9\u53EA\u662F\u4ED6\u7684\u4E00\u9762\u4E4B\u8BCD\u3002\u7ECF\u7EF4\u57FA\u641C\u7D22\u6458\u8981\u5370\u8BC1\u3002"}},{ref:"acok",checked:"memory",note:{en:"Dragonstone's Valyrian fused-stone castle, as an example of the building technique; recalled, not re-read.",zh:"\u9F99\u77F3\u5C9B\u7684\u74E6\u96F7\u5229\u4E9A\u7194\u77F3\u57CE\u5821\uFF0C\u4F5C\u4E3A\u8FD9\u79CD\u8425\u9020\u6280\u827A\u7684\u4F8B\u8BC1\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"The Fourteen Flames, the peninsula shattered into islands, and failed expeditions to the ruins, as reported in wiki search summaries; the book itself was not checked.",zh:"\u5341\u56DB\u706B\u5CF0\u3001\u534A\u5C9B\u788E\u88C2\u6210\u7FA4\u5C9B\u3001\u63A2\u7D22\u5E9F\u589F\u7684\u8FDC\u5F81\u5C61\u5C61\u5931\u8D25\u7B49\u5185\u5BB9\uFF0C\u89C1\u4E8E\u7EF4\u57FA\u641C\u7D22\u6458\u8981\uFF1B\u672A\u67E5\u9605\u539F\u4E66\u3002"}}],landmarks:{"fourteen-flames":e("Fourteen Flames","\u5341\u56DB\u706B\u5CF0",["The volcanoes at the heart of the Freehold, whose eruption destroyed Valyria. Here a ring of smoking cones surrounds the city.","\u81EA\u7531\u5821\u5792\u8179\u5730\u7684\u706B\u5C71\u7FA4\uFF0C\u5B83\u4EEC\u7684\u55B7\u53D1\u6BC1\u706D\u4E86\u74E6\u96F7\u5229\u4E9A\u3002\u672C\u573A\u666F\u4E2D\uFF0C\u5192\u70DF\u7684\u706B\u5C71\u9525\u73AF\u7ED5\u7740\u57CE\u533A\u3002"],["When the Fourteen Flames erupted, a whole civilisation ended.","\u5341\u56DB\u706B\u5CF0\u7206\u53D1\u4E4B\u65F6\uFF0C\u4E00\u4E2A\u6587\u660E\u5C31\u6B64\u7EC8\u7ED3\u3002"],"medium",["twoiaf","adwd"],["Valyria was built around a chain of fourteen volcanoes that erupted in the Doom; a red glow can still be seen from the sea.","\u74E6\u96F7\u5229\u4E9A\u5EFA\u5728\u5341\u56DB\u5EA7\u706B\u5C71\u6784\u6210\u7684\u5C71\u94FE\u5468\u56F4\uFF0C\u706B\u5C71\u5728\u672B\u65E5\u6D69\u52AB\u4E2D\u7206\u53D1\uFF1B\u5982\u4ECA\u4ECE\u6D77\u4E0A\u4ECD\u53EF\u671B\u89C1\u7EA2\u5149\u3002"],["Their exact positions and how the city lay among them.","\u5B83\u4EEC\u7684\u786E\u5207\u4F4D\u7F6E\uFF0C\u4EE5\u53CA\u57CE\u5E02\u5728\u5176\u95F4\u5982\u4F55\u5206\u5E03\u3002"],["Fourteen cones in a loose arc with glowing rims and ash plumes.","\u5341\u56DB\u5EA7\u706B\u5C71\u9525\u6392\u6210\u677E\u6563\u7684\u5F27\u5F62\uFF0C\u706B\u53E3\u53D1\u7EA2\uFF0C\u7070\u70DF\u5347\u817E\u3002"]),"shattered-towers":e("Shattered Towers","\u6B8B\u5854",["Broken towers, fallen drums and tilted walls: the imagined rubble of the dragonlords' city.","\u65AD\u5854\u3001\u5012\u584C\u7684\u5854\u8EAB\u4E0E\u503E\u659C\u7684\u5899\uFF1A\u60F3\u8C61\u4E2D\u7684\u9F99\u738B\u4E4B\u57CE\u7684\u6B8B\u57A3\u65AD\u58C1\u3002"],["Only stumps remain of the towers we imagine for the dragonlords.","\u6211\u4EEC\u60F3\u8C61\u4E2D\u9F99\u738B\u4EEC\u7684\u9AD8\u5854\uFF0C\u5982\u4ECA\u53EA\u5269\u6B8B\u6869\u3002"],"low",["affc","twoiaf"],["Ruins are said to remain, but no trustworthy description of them exists.","\u636E\u8BF4\u5E9F\u589F\u5C1A\u5B58\uFF0C\u4F46\u6CA1\u6709\u53EF\u4FE1\u7684\u63CF\u8FF0\u3002"],["What the buildings looked like and what survives.","\u5EFA\u7B51\u539F\u8C8C\u4E0E\u6B8B\u5B58\u60C5\u51B5\u3002"],["Ten broken stone towers with collapsed sections; entirely invented.","\u5341\u5EA7\u65AD\u88C2\u7684\u77F3\u5854\u4E0E\u574D\u584C\u7684\u6B8B\u6BB5\uFF1B\u5B8C\u5168\u4E3A\u81EA\u62DF\u3002"]),"fused-stone":e("Fused Stone","\u7194\u77F3",["Black, glassy stone: the Valyrians built in dragon-fused stone, and here the Doom has melted the ground as well.","\u9ED1\u8272\u73BB\u7483\u72B6\u7684\u77F3\u5934\uFF1A\u74E6\u96F7\u5229\u4E9A\u4EBA\u4EE5\u9F99\u7130\u7194\u77F3\u8425\u9020\uFF0C\u800C\u5728\u8FD9\u91CC\uFF0C\u672B\u65E5\u6D69\u52AB\u4E5F\u628A\u5927\u5730\u7194\u6210\u4E86\u540C\u6837\u7684\u77F3\u5934\u3002"],["Valyrians shaped stone with fire. Here the fire turned on them.","\u74E6\u96F7\u5229\u4E9A\u4EBA\u4EE5\u706B\u5851\u77F3\u3002\u5728\u8FD9\u91CC\uFF0C\u706B\u7130\u53CD\u566C\u4E86\u4ED6\u4EEC\u3002"],"low",["acok","adwd"],["Valyrian fused stone is known from surviving works such as Dragonstone and the Black Walls of Volantis; nothing describes the ground of Valyria itself.","\u74E6\u96F7\u5229\u4E9A\u7194\u77F3\u89C1\u4E8E\u9F99\u77F3\u5C9B\u3001\u74E6\u5170\u63D0\u65AF\u9ED1\u5899\u7B49\u7559\u5B58\u5EFA\u7B51\uFF1B\u74E6\u96F7\u5229\u4E9A\u672C\u571F\u7684\u5730\u8C8C\u5219\u6BEB\u65E0\u63CF\u5199\u3002"],["Whether any such stone or slag lies on the peninsula.","\u534A\u5C9B\u4E0A\u662F\u5426\u6709\u6B64\u7C7B\u7194\u77F3\u6216\u7194\u6E23\u3002"],["Dark glossy shards and slag domes scattered across the plain.","\u6563\u5E03\u5E73\u539F\u7684\u6DF1\u8272\u4EAE\u9762\u788E\u7247\u4E0E\u7194\u6E23\u4E18\u3002"]),"valyrian-road":e("Valyrian Road","\u74E6\u96F7\u5229\u4E9A\u5927\u9053",["A straight, seamless stone road, broken where the earth has split.","\u4E00\u6761\u7B14\u76F4\u3001\u6D51\u7136\u65E0\u7F1D\u7684\u77F3\u8DEF\uFF0C\u5728\u5927\u5730\u5F00\u88C2\u5904\u65AD\u5F00\u3002"],["Valyrian roads still cross Essos, outlasting the empire that built them.","\u74E6\u96F7\u5229\u4E9A\u5927\u9053\u81F3\u4ECA\u4ECD\u6A2A\u8D2F\u5384\u7D22\u65AF\uFF0C\u6BD4\u4FEE\u5EFA\u5B83\u4EEC\u7684\u5E1D\u56FD\u66F4\u4E3A\u957F\u4E45\u3002"],"medium",["adwd","twoiaf"],["The Freehold built long roads of fused stone that still serve travellers in Essos.","\u81EA\u7531\u5821\u5792\u4FEE\u5EFA\u4E86\u7194\u77F3\u957F\u8DEF\uFF0C\u81F3\u4ECA\u4ECD\u4F9B\u5384\u7D22\u65AF\u7684\u65C5\u4EBA\u4F7F\u7528\u3002"],["Whether any road survives on the peninsula, and where.","\u534A\u5C9B\u4E0A\u662F\u5426\u8FD8\u6709\u9053\u8DEF\u7559\u5B58\uFF0C\u53C8\u5728\u4F55\u5904\u3002"],["A straight dark road across the plain, cut by fissures.","\u4E00\u6761\u6A2A\u8D2F\u5E73\u539F\u7684\u7B14\u76F4\u6697\u8272\u9053\u8DEF\uFF0C\u88AB\u88C2\u9699\u622A\u65AD\u3002"]),"smoking-sea":e("Smoking Sea","\u70DF\u6D77",["Hot, steaming water wrapped in sulphur, which sailors avoid.","\u84B8\u6C7D\u817E\u817E\u3001\u786B\u78FA\u5F25\u6F2B\u7684\u70BD\u70ED\u6D77\u57DF\uFF0C\u6C34\u624B\u907F\u4E4B\u552F\u6050\u4E0D\u53CA\u3002"],["Steam rises from the water; sailors say demons haunt these shores.","\u6D77\u9762\u84B8\u6C7D\u5347\u817E\uFF1B\u6C34\u624B\u4EEC\u8BF4\uFF0C\u8FD9\u7247\u6D77\u5CB8\u6709\u6076\u9B54\u51FA\u6CA1\u3002"],"high",["adwd","twoiaf"],["The sea around Valyria smokes and is feared as cursed; expeditions into it have failed.","\u74E6\u96F7\u5229\u4E9A\u5468\u56F4\u7684\u6D77\u57DF\u70DF\u96FE\u5347\u817E\uFF0C\u88AB\u89C6\u4E3A\u53D7\u8BC5\u5492\u4E4B\u5730\uFF1B\u6DF1\u5165\u5176\u4E2D\u7684\u8FDC\u5F81\u65E0\u4E0D\u5931\u8D25\u3002"],["Its exact extent and true dangers.","\u786E\u5207\u8303\u56F4\u4E0E\u771F\u6B63\u7684\u5371\u9669\u3002"],["A band of steam along the southern shore.","\u6CBF\u5357\u5CB8\u7684\u4E00\u5E26\u84B8\u6C7D\u3002"]),"fire-fissures":e("Fire Fissures","\u706B\u88C2\u9699",["Deep cracks glowing red, with smoking vents.","\u6CDB\u7740\u7EA2\u5149\u7684\u6DF1\u88C2\u7F1D\uFF0C\u55B7\u53E3\u5192\u70DF\u3002"],["The land is split, and the glow below has not gone out.","\u5927\u5730\u5F00\u88C2\uFF0C\u5730\u5E95\u7684\u706B\u5149\u4ECD\u672A\u7184\u706D\u3002"],"low",["twoiaf"],["Nothing describes fissures; only a distant red glow is reported.","\u6CA1\u6709\u5173\u4E8E\u88C2\u9699\u7684\u8BB0\u8F7D\uFF1B\u53EA\u6709\u8FDC\u5904\u7EA2\u5149\u7684\u63CF\u8FF0\u3002"],["Whether anything like this exists.","\u662F\u5426\u5B58\u5728\u8FD9\u6837\u7684\u666F\u8C61\u3002"],["Three glowing chasms crossing the ruins; invented.","\u4E09\u9053\u53D1\u5149\u7684\u6DF1\u58D1\u6A2A\u7A7F\u5E9F\u589F\uFF1B\u4E3A\u81EA\u62DF\u3002"])}};export{d as default};
